css:
.loader {
  overflow: hidden;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;

  .poly {
    fill: none;
    stroke: yellow;
    stroke-width: 16;
    transform-origin: center center;
    animation: move 10s linear infinite;
    animation-delay: calc(var(--i) * -0.5s);
  }
}

@keyframes move {
  0% {
    transform: scale(0) rotate(0);
    opacity: 1;
  }
  100% {
    transform: scale(3) rotate(45deg);
    opacity: 0;
  }
}
